// Claude's review tests for A13 (templates in a fixed body). agy: do not edit this file.
import { describe, expect, it } from 'vitest';
import { buildInput } from './handler';
import { fillTemplate } from './template';
import type { Mock } from './types';

function mock(extra: Partial<Mock> = {}): Mock {
  return {
    id: 'm',
    enabled: true,
    method: 'ANY',
    urlPattern: '/api/users/:id',
    response: { status: 200, headers: {}, body: '', bodyEncoding: 'text', delayMs: 0 },
    source: 'manual',
    createdAt: 0,
    ...extra,
  };
}

const req = buildInput(mock(), {
  method: 'POST',
  url: 'http://a.test/api/users/7?page=2&tag=a&tag=b',
  headers: { 'X-User': 'anna' },
  body: '{"user":{"name":"Anna","age":30,"admin":false},"items":[{"id":11},{"id":12}]}',
}).req;

const deps = { now: () => new Date('2026-11-09T10:20:30.000Z'), uuid: () => 'u-1' };
const fill = (text: string) => fillTemplate(text, req, deps);

describe('fillTemplate', () => {
  it('fills params, query, headers and body paths', () => {
    expect(fill('{"id":{{params.id}},"page":"{{query.page}}","who":"{{headers.x-user}}","name":"{{body.user.name}}"}'))
      .toBe('{"id":7,"page":"2","who":"anna","name":"Anna"}');
  });
  it('header names are case-insensitive', () => {
    expect(fill('{{headers.X-USER}}')).toBe('anna');
  });
  it('a repeated query key gives its first value', () => {
    expect(fill('{{query.tag}}')).toBe('a');
  });
  it('array items by index, numbers and booleans as text, objects as JSON', () => {
    expect(fill('{{body.items.1.id}}')).toBe('12');
    expect(fill('{{body.user.age}}|{{body.user.admin}}')).toBe('30|false');
    expect(fill('{{body.items.0}}')).toBe('{"id":11}');
  });
  it('uuid, now and timestamp', () => {
    expect(fill('{{uuid}} {{now}} {{timestamp}}')).toBe('u-1 2026-11-09T10:20:30.000Z 1794219630000');
  });
  it('spaces inside the braces are allowed', () => {
    expect(fill('{{ params.id }}')).toBe('7');
  });
  it('a missing value becomes empty', () => {
    expect(fill('[{{query.nope}}][{{body.user.nope.deeper}}][{{params.nope}}][{{headers.nope}}]')).toBe('[][][][]');
  });
  it('unknown names stay as written', () => {
    expect(fill('{{hello}} {{ user.name }} {{}}')).toBe('{{hello}} {{ user.name }} {{}}');
  });
  it('\\{{ is a literal {{', () => {
    expect(fill('\\{{params.id}} {{params.id}}')).toBe('{{params.id}} 7');
  });
  it('a text with no braces comes back unchanged', () => {
    expect(fill('plain { text }')).toBe('plain { text }');
  });
  it('the body path works on a text body only through body as a whole', () => {
    const textReq = buildInput(mock(), { method: 'POST', url: 'http://a.test/api/users/1', headers: {}, body: 'hello' }).req;
    expect(fillTemplate('{{body}}|{{body.x}}', textReq, deps)).toBe('hello|');
  });
  it('uuid and now default to real values', () => {
    const out = fillTemplate('{{uuid}}|{{now}}', req);
    const [u, n] = out.split('|');
    expect(u).toMatch(/^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/);
    expect(Number.isNaN(Date.parse(n!))).toBe(false);
  });
});

describe('fillTemplate with a wildcard param', () => {
  it('a params array gives its first value', () => {
    const wild = buildInput(mock({ urlPattern: '/files/*path' }), { method: 'GET', url: 'http://a.test/files/a/b', headers: {} }).req;
    expect(Array.isArray(wild.params.path)).toBe(true);
    expect(fillTemplate('{{params.path}}', wild, deps)).toBe('a');
  });
});
